static
void kernel_adi(int tsteps, int n,
		DATA_TYPE POLYBENCH_2D(u,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(v,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(p,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(q,N,N,n,n))
{
  int t, i, j;
  DATA_TYPE DX, DY, DT;
  DATA_TYPE B1, B2;
  DATA_TYPE mul1, mul2;
  DATA_TYPE a, b, c, d, e, f;

#pragma scop

  DX = SCALAR_VAL(1.0)/(DATA_TYPE)_PB_N;
  DY = SCALAR_VAL(1.0)/(DATA_TYPE)_PB_N;
  DT = SCALAR_VAL(1.0)/(DATA_TYPE)_PB_TSTEPS;
  B1 = SCALAR_VAL(2.0);
  B2 = SCALAR_VAL(1.0);
  mul1 = B1 * DT / (DX * DX);
  mul2 = B2 * DT / (DY * DY);

  a = -mul1 /  SCALAR_VAL(2.0);
  b = SCALAR_VAL(1.0)+mul1;
  c = a;
  d = -mul2 / SCALAR_VAL(2.0);
  e = SCALAR_VAL(1.0)+mul2;
  f = d;

  const DATA_TYPE one = SCALAR_VAL(1.0);
  const DATA_TYPE two = SCALAR_VAL(2.0);

  for (t=1; t<=_PB_TSTEPS; t++) {
    for (i=1; i<_PB_N-1; i++) {
      v[0][i] = one;
      p[i][0] = SCALAR_VAL(0.0);
      q[i][0] = v[0][i];

      for (j=1; j<_PB_N-1; j++) {
        DATA_TYPE denom = a * p[i][j-1] + b;
        p[i][j] = -c / denom;
        q[i][j] = (-d * u[j][i-1] + (one + two * d) * u[j][i] - f * u[j][i+1] - a * q[i][j-1]) / denom;
      }

      v[_PB_N-1][i] = one;
      for (j=_PB_N-2; j>=1; j--) {
        v[j][i] = p[i][j] * v[j+1][i] + q[i][j];
      }
    }

    for (i=1; i<_PB_N-1; i++) {
      u[i][0] = one;
      p[i][0] = SCALAR_VAL(0.0);
      q[i][0] = u[i][0];

      for (j=1; j<_PB_N-1; j++) {
        DATA_TYPE denom = d * p[i][j-1] + e;
        p[i][j] = -f / denom;
        q[i][j] = (-a * v[i-1][j] + (one + two * a) * v[i][j] - c * v[i+1][j] - d * q[i][j-1]) / denom;
      }

      u[i][_PB_N-1] = one;
      for (j=_PB_N-2; j>=1; j--) {
        u[i][j] = p[i][j] * u[i][j+1] + q[i][j];
      }
    }
  }
#pragma endscop
}

