static
void kernel_atax(int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
		 DATA_TYPE POLYBENCH_1D(x,N,n),
		 DATA_TYPE POLYBENCH_1D(y,N,n),
		 DATA_TYPE POLYBENCH_1D(tmp,M,m))
{
  int i, j;

#pragma scop
  for (i = 0; i < _PB_N; i++)
    y[i] = 0;

  for (i = 0; i < _PB_M; i++)
    {
      tmp[i] = SCALAR_VAL(0.0);

      j = 0;
      while (j < _PB_N)
	{
	  size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_N - j));
	  vfloat64m1_t va = __riscv_vle64_v_f64m1(&A[i][j], vl);
	  vfloat64m1_t vx = __riscv_vle64_v_f64m1(&x[j], vl);
	  vfloat64m1_t vm = __riscv_vfmul_vv_f64m1(va, vx, vl);

	  vfloat64m1_t vtmp = __riscv_vle64_v_f64m1(&tmp[i], 1);
	  vtmp = __riscv_vfredosum_vs_f64m1_f64m1(vm, vtmp, vl);
	  tmp[i] = __riscv_vfmv_f_s_f64m1_f64(vtmp);

	  j += (int)vl;
	}

      j = 0;
      while (j < _PB_N)
	{
	  size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_N - j));
	  vfloat64m1_t va = __riscv_vle64_v_f64m1(&A[i][j], vl);
	  vfloat64m1_t vy = __riscv_vle64_v_f64m1(&y[j], vl);
	  vfloat64m1_t vtmp = __riscv_vfmv_v_f_f64m1(tmp[i], vl);
	  vfloat64m1_t vm = __riscv_vfmul_vv_f64m1(va, vtmp, vl);
	  vy = __riscv_vfadd_vv_f64m1(vy, vm, vl);
	  __riscv_vse64_v_f64m1(&y[j], vy, vl);

	  j += (int)vl;
	}
    }
#pragma endscop

}

