static
void kernel_durbin(int n,
		   DATA_TYPE POLYBENCH_1D(r,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n))
{
  DATA_TYPE z[N];
  DATA_TYPE alpha;
  DATA_TYPE beta;
  DATA_TYPE sum;

  int i, k;

#pragma scop
  y[0] = -r[0];
  beta = SCALAR_VAL(1.0);
  alpha = -r[0];

  for (k = 1; k < _PB_N; k++) {
    beta = (1 - alpha * alpha) * beta;
    sum = SCALAR_VAL(0.0);

    int i = 0;
    for (; i < k; i++) {
      sum += r[k - i - 1] * y[i];
    }

    alpha = - (r[k] + sum) / beta;

    int j = 0;
    for (; j < k; j++) {
      z[j] = y[j] + alpha * y[k - j - 1];
    }

    j = 0;
    for (; j < k; j++) {
      y[j] = z[j];
    }

    y[k] = alpha;
  }
#pragma endscop
}

