static
void kernel_fdtd_2d(int tmax,
		    int nx,
		    int ny,
		    DATA_TYPE POLYBENCH_2D(ex,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_2D(ey,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_2D(hz,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_1D(_fict_,TMAX,tmax))
{
  int t, i, j;
  const DATA_TYPE c05 = SCALAR_VAL(0.5);
  const DATA_TYPE c07 = SCALAR_VAL(0.7);

#pragma scop

  for (t = 0; t < _PB_TMAX; t++)
    {
      DATA_TYPE *ey0 = ey[0];
      for (j = 0; j < _PB_NY; j++)
	ey0[j] = _fict_[t];

      for (i = 1; i < _PB_NX; i++)
	{
	  DATA_TYPE *eyi = ey[i];
	  DATA_TYPE *hzi = hz[i];
	  DATA_TYPE *hzim1 = hz[i - 1];

	  j = 0;
	  while (j < _PB_NY)
	    {
	      size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_NY - j));
	      vfloat64m1_t vey = __riscv_vle64_v_f64m1(eyi + j, vl);
	      vfloat64m1_t vhz = __riscv_vle64_v_f64m1(hzi + j, vl);
	      vfloat64m1_t vhzp = __riscv_vle64_v_f64m1(hzim1 + j, vl);
	      vfloat64m1_t vdiff = __riscv_vfsub_vv_f64m1(vhz, vhzp, vl);
	      vfloat64m1_t vhalf = __riscv_vfmul_vf_f64m1(vdiff, c05, vl);
	      vey = __riscv_vfsub_vv_f64m1(vey, vhalf, vl);
	      __riscv_vse64_v_f64m1(eyi + j, vey, vl);
	      j += (int)vl;
	    }
	}

      for (i = 0; i < _PB_NX; i++)
	{
	  DATA_TYPE *exi = ex[i];
	  DATA_TYPE *hzi = hz[i];

	  j = 1;
	  while (j < _PB_NY)
	    {
	      size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_NY - j));
	      vfloat64m1_t vex = __riscv_vle64_v_f64m1(exi + j, vl);
	      vfloat64m1_t vhz = __riscv_vle64_v_f64m1(hzi + j, vl);
	      vfloat64m1_t vhzp = __riscv_vle64_v_f64m1(hzi + j - 1, vl);
	      vfloat64m1_t vdiff = __riscv_vfsub_vv_f64m1(vhz, vhzp, vl);
	      vfloat64m1_t vhalf = __riscv_vfmul_vf_f64m1(vdiff, c05, vl);
	      vex = __riscv_vfsub_vv_f64m1(vex, vhalf, vl);
	      __riscv_vse64_v_f64m1(exi + j, vex, vl);
	      j += (int)vl;
	    }
	}

      for (i = 0; i < _PB_NX - 1; i++)
	{
	  DATA_TYPE *hzi = hz[i];
	  DATA_TYPE *exi = ex[i];
	  DATA_TYPE *eyi = ey[i];
	  DATA_TYPE *eyip1 = ey[i + 1];

	  j = 0;
	  while (j < _PB_NY - 1)
	    {
	      size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_NY - 1 - j));
	      vfloat64m1_t vhz = __riscv_vle64_v_f64m1(hzi + j, vl);
	      vfloat64m1_t vex1 = __riscv_vle64_v_f64m1(exi + j + 1, vl);
	      vfloat64m1_t vex0 = __riscv_vle64_v_f64m1(exi + j, vl);
	      vfloat64m1_t vey1 = __riscv_vle64_v_f64m1(eyip1 + j, vl);
	      vfloat64m1_t vey0 = __riscv_vle64_v_f64m1(eyi + j, vl);

	      vfloat64m1_t vdiff = __riscv_vfsub_vv_f64m1(vex1, vex0, vl);
	      vfloat64m1_t vdiff2 = __riscv_vfsub_vv_f64m1(vey1, vey0, vl);
	      vdiff = __riscv_vfadd_vv_f64m1(vdiff, vdiff2, vl);
	      vfloat64m1_t vmul = __riscv_vfmul_vf_f64m1(vdiff, c07, vl);
	      vhz = __riscv_vfsub_vv_f64m1(vhz, vmul, vl);
	      __riscv_vse64_v_f64m1(hzi + j, vhz, vl);
	      j += (int)vl;
	    }
	}
    }

#pragma endscop
}

