static
void kernel_floyd_warshall(int n,
			   DATA_TYPE POLYBENCH_2D(path,N,N,n,n))
{
  int i, j, k;

#pragma scop
  for (k = 0; k < _PB_N; k++)
    {
      for (i = 0; i < _PB_N; i++)
	{
	  const DATA_TYPE pik = path[i][k];
	  int j = 0;

	  while (j < _PB_N)
	    {
	      size_t vl = __riscv_vsetvl_e32m8((size_t)(_PB_N - j));

	      vfloat32m8_t v_ij = __riscv_vle32_v_f32m8((const float *)&path[i][j], vl);
	      vfloat32m8_t v_kj = __riscv_vle32_v_f32m8((const float *)&path[k][j], vl);
	      vfloat32m8_t v_pik = __riscv_vfmv_v_f_f32m8((float)pik, vl);
	      vfloat32m8_t v_sum = __riscv_vfadd_vv_f32m8(v_pik, v_kj, vl);
	      vfloat32m8_t v_min = __riscv_vfmin_vv_f32m8(v_ij, v_sum, vl);

	      __riscv_vse32_v_f32m8((float *)&path[i][j], v_min, vl);
	      j += (int)vl;
	    }
	}
    }
#pragma endscop
}

