static
void kernel_gemm(int ni, int nj, int nk,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj),
		 DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		 DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_NI; i++) {
    DATA_TYPE *ci = C[i];

    j = 0;
    while (j < _PB_NJ) {
      size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_NJ - j));
      vfloat64m1_t vc = __riscv_vle64_v_f64m1(ci + j, vl);
      vc = __riscv_vfmul_vf_f64m1(vc, beta, vl);
      __riscv_vse64_v_f64m1(ci + j, vc, vl);
      j += (int)vl;
    }

    for (k = 0; k < _PB_NK; k++) {
      DATA_TYPE aik = A[i][k];
      const DATA_TYPE *bk = B[k];

      j = 0;
      while (j < _PB_NJ) {
        size_t vl = __riscv_vsetvl_e64m1((size_t)(_PB_NJ - j));

        vfloat64m1_t vc = __riscv_vle64_v_f64m1(ci + j, vl);
        vfloat64m1_t vb = __riscv_vle64_v_f64m1(bk + j, vl);
        vfloat64m1_t va = __riscv_vfmv_v_f_f64m1(aik, vl);
        vfloat64m1_t vm = __riscv_vfmul_vv_f64m1(va, vb, vl);
        vfloat64m1_t vs = __riscv_vfmul_vf_f64m1(vm, alpha, vl);
        vc = __riscv_vfadd_vv_f64m1(vc, vs, vl);

        __riscv_vse64_v_f64m1(ci + j, vc, vl);
        j += (int)vl;
      }
    }
  }
#pragma endscop
}

