static
void kernel_heat_3d(int tsteps,
		      int n,
		      DATA_TYPE POLYBENCH_3D(A,N,N,N,n,n,n),
		      DATA_TYPE POLYBENCH_3D(B,N,N,N,n,n,n))
{
  int t, i, j, k;
  const int limit = _PB_N - 1;
  const DATA_TYPE c125 = SCALAR_VAL(0.125);
  const DATA_TYPE c200 = SCALAR_VAL(2.0);

#pragma scop
  for (t = 1; t <= TSTEPS; t++) {
    for (i = 1; i < limit; i++) {
      for (j = 1; j < limit; j++) {
        for (k = 1; k < limit; k++) {
          B[i][j][k] =   c125 * (A[i+1][j][k] - c200 * A[i][j][k] + A[i-1][j][k])
                       + c125 * (A[i][j+1][k] - c200 * A[i][j][k] + A[i][j-1][k])
                       + c125 * (A[i][j][k+1] - c200 * A[i][j][k] + A[i][j][k-1])
                       + A[i][j][k];
        }
      }
    }

    for (i = 1; i < limit; i++) {
      for (j = 1; j < limit; j++) {
        for (k = 1; k < limit; k++) {
          A[i][j][k] =   c125 * (B[i+1][j][k] - c200 * B[i][j][k] + B[i-1][j][k])
                       + c125 * (B[i][j+1][k] - c200 * B[i][j][k] + B[i][j-1][k])
                       + c125 * (B[i][j][k+1] - c200 * B[i][j][k] + B[i][j][k-1])
                       + B[i][j][k];
        }
      }
    }
#pragma endscop
}

