static
void kernel_jacobi_2d(int tsteps,
			    int n,
			    DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
			    DATA_TYPE POLYBENCH_2D(B,N,N,n,n))
{
  int t, i, j;
  const DATA_TYPE scalar = SCALAR_VAL(0.2);

#pragma scop
  for (t = 0; t < _PB_TSTEPS; t++)
    {
      for (i = 1; i < _PB_N - 1; i++)
	{
	  int j = 1;
	  for (; j + 3 < _PB_N - 1; j += 4)
	    {
	      size_t vl = __riscv_vsetvl_e64m1(4);

	      vfloat64m1_t va0 = __riscv_vle64_v_f64m1(&A[i][j], vl);
	      vfloat64m1_t va1 = __riscv_vle64_v_f64m1(&A[i][j - 1], vl);
	      vfloat64m1_t va2 = __riscv_vle64_v_f64m1(&A[i][j + 1], vl);
	      vfloat64m1_t va3 = __riscv_vle64_v_f64m1(&A[i + 1][j], vl);
	      vfloat64m1_t va4 = __riscv_vle64_v_f64m1(&A[i - 1][j], vl);

	      vfloat64m1_t sum = __riscv_vfadd_vv_f64m1(va0, va1, vl);
	      sum = __riscv_vfadd_vv_f64m1(sum, va2, vl);
	      sum = __riscv_vfadd_vv_f64m1(sum, va3, vl);
	      sum = __riscv_vfadd_vv_f64m1(sum, va4, vl);

	      vfloat64m1_t out = __riscv_vfmul_vf_f64m1(sum, scalar, vl);
	      __riscv_vse64_v_f64m1(&B[i][j], out, vl);
	    }
	  for (; j < _PB_N - 1; j++)
	    B[i][j] = scalar * (A[i][j] + A[i][j-1] + A[i][1+j] + A[1+i][j] + A[i-1][j]);
	}

      for (i = 1; i < _PB_N - 1; i++)
	{
	  int j = 1;
	  for (; j + 3 < _PB_N - 1; j += 4)
	    {
	      size_t vl = __riscv_vsetvl_e64m1(4);

	      vfloat64m1_t vb0 = __riscv_vle64_v_f64m1(&B[i][j], vl);
	      vfloat64m1_t vb1 = __riscv_vle64_v_f64m1(&B[i][j - 1], vl);
	      vfloat64m1_t vb2 = __riscv_vle64_v_f64m1(&B[i][j + 1], vl);
	      vfloat64m1_t vb3 = __riscv_vle64_v_f64m1(&B[i + 1][j], vl);
	      vfloat64m1_t vb4 = __riscv_vle64_v_f64m1(&B[i - 1][j], vl);

	      vfloat64m1_t sum = __riscv_vfadd_vv_f64m1(vb0, vb1, vl);
	      sum = __riscv_vfadd_vv_f64m1(sum, vb2, vl);
	      sum = __riscv_vfadd_vv_f64m1(sum, vb3, vl);
	      sum = __riscv_vfadd_vv_f64m1(sum, vb4, vl);

	      vfloat64m1_t out = __riscv_vfmul_vf_f64m1(sum, scalar, vl);
	      __riscv_vse64_v_f64m1(&A[i][j], out, vl);
	    }
	  for (; j < _PB_N - 1; j++)
	    A[i][j] = scalar * (B[i][j] + B[i][j-1] + B[i][1+j] + B[1+i][j] + B[i-1][j]);
	}
    }
#pragma endscop

}

