static
void kernel_lu(int n,
	       DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_N; i++) {
    for (j = 0; j < i; j++) {
      DATA_TYPE sum = 0.0;
      for (k = 0; k < j; k++) {
        sum += A[i][k] * A[k][j];
      }
      A[i][j] -= sum;
      A[i][j] /= A[j][j];
    }
    for (j = i; j < _PB_N; j++) {
      DATA_TYPE sum = 0.0;
      for (k = 0; k < i; k++) {
        sum += A[i][k] * A[k][j];
      }
      A[i][j] -= sum;
    }
  }
#pragma endscop
}

