    DATA_TYPE acc = x1[i];
    for (j = 0; j < _PB_N; j++) {
      acc = acc + A[i][j] * y_1[j];
    }
    x1[i] = acc;
  }

  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE acc = x2[i];
